CREATE TABLE el_branch_logos(org_id TEXT NOT NULL,branch_id TEXT NOT NULL,version TEXT NOT NULL,mime TEXT NOT NULL CHECK(mime IN ('image/png','image/jpeg')),byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 32768),iv TEXT NOT NULL,ciphertext TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,branch_id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,updated_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_branch_logo_identity BEFORE UPDATE ON el_branch_logos WHEN NEW.org_id<>OLD.org_id OR NEW.branch_id<>OLD.branch_id BEGIN SELECT RAISE(ABORT,'Branch logo identity is immutable'); END;
